<template><view class="page"><text class="title">我的曲谱</text><view class="field"><text>曲名</text><input v-model="name" :disabled="uploading" maxlength="20" placeholder="MY_SONG" /></view><view class="field row"><view><text>节拍（ms）</text><input v-model.number="beatMs" :disabled="uploading" type="number" /></view><button :disabled="uploading" @click="arrange">按节拍自动排列</button></view><view class="actions"><button :disabled="uploading || notes.length >= 42" @click="addNote">新增音符</button><button :disabled="uploading" @click="preview">{{ playing ? '停止' : '试听' }}</button></view><view v-for="(item,index) in notes" :key="index" class="note"><input v-model.number="item.timeMs" :disabled="uploading" type="number" /><picker :range="noteNames" :value="item.note" :disabled="uploading" @change="changeNote(index,$event)"><view>{{ noteNames[item.note] }}</view></picker><button :disabled="uploading" @click="removeNote(index)">删除</button></view><text class="summary">共 {{ notes.length }} 个音符</text><button class="upload" :disabled="uploading" @click="upload">{{ uploading ? uploadLabel : '上传曲谱' }}</button><button v-if="uploading" class="cancel" @click="cancelUpload">取消上传</button></view></template>
<script>
import spp from '../../services/spp.js'
import * as tone from '../../utils/tone.js'
export default { data(){return{name:'MY_SONG',beatMs:600,notes:[{timeMs:0,note:0}],noteNames:['Do','Re','Mi','Fa','Sol','La','Si'],playing:false,uploading:false,uploadState:'idle',uploadIndex:0,uploadNotes:[],unsubscribe:null}}, computed:{uploadLabel(){return this.uploadState==='begin'?'正在开始上传…':this.uploadState==='commit'?'正在提交…':`正在上传 ${this.uploadIndex+1}/${this.uploadNotes.length}`}}, onShow(){this.unsubscribe=spp.subscribe(this.onSppEvent)},onHide(){tone.stop();this.playing=false;if(this.uploading)this.abort('上传已取消')},onUnload(){tone.stop();if(this.unsubscribe)this.unsubscribe()},onBackPress(){if(this.uploading){this.cancelUpload();return true}},methods:{
check(){const name=String(this.name||'').trim().toUpperCase(),beat=Number(this.beatMs);if(!/^[A-Z0-9_]{1,20}$/.test(name))return'曲名仅限 A-Z、0-9、下划线';if(!Number.isInteger(beat)||beat<200||beat>2000)return'节拍范围为 200–2000 ms';if(!this.notes.length||this.notes.length>42)return'音符数量应为 1–42';let last=-1;for(const n of this.notes){if(!Number.isInteger(Number(n.timeMs))||Number(n.timeMs)<0||Number(n.timeMs)<=last)return'时间必须严格递增';if(!Number.isInteger(Number(n.note))||n.note<0||n.note>6)return'音符无效';last=Number(n.timeMs)}return{name,beat,notes:this.notes.map(n=>({timeMs:Number(n.timeMs),note:Number(n.note)}))}},
arrange(){const beat=Number(this.beatMs);if(!Number.isInteger(beat)||beat<200||beat>2000)return uni.showToast({title:'节拍范围为 200–2000 ms',icon:'none'});this.notes.forEach((n,i)=>{n.timeMs=i*beat})},addNote(){const beat=Number(this.beatMs);if(this.notes.length>=42)return;if(!Number.isInteger(beat)||beat<200||beat>2000)return uni.showToast({title:'请先填写合法节拍',icon:'none'});const last=this.notes[this.notes.length-1];this.notes.push({timeMs:Number(last.timeMs)+beat,note:0})},removeNote(i){if(this.notes.length>1)this.notes.splice(i,1);else uni.showToast({title:'曲谱至少保留一个音符',icon:'none'})},changeNote(i,e){this.notes[i].note=Number(e.detail.value)},preview(){if(this.playing){tone.stop();this.playing=false;return}const data=this.check();if(typeof data==='string')return uni.showToast({title:data,icon:'none'});this.playing=tone.play(data.notes.map(n=>({...n,band:1})),()=>{this.playing=false});if(!this.playing)uni.showToast({title:'当前环境无法试听',icon:'none'})},
upload(){const data=this.check();if(typeof data==='string')return uni.showToast({title:data,icon:'none'});if(!spp.socket)return uni.showToast({title:'请先连接设备',icon:'none'});uni.showModal({title:'上传曲谱',content:`共 ${data.notes.length} 个音符，预计上传很快`,success:r=>{if(!r.confirm)return;this.name=data.name;this.uploading=true;this.uploadState='begin';this.uploadIndex=0;this.uploadNotes=data.notes;if(!spp.send(`M2,UPLOAD,BEGIN,${data.name},${data.beat},${data.notes.length}\n`))this.abort('上传失败，请重新连接')}})},
onSppEvent(e){if(e.type==='status'&&e.state!=='已连接'){if(this.uploading)this.abort('连接已断开',false);return}if(e.type!=='frame'||!this.uploading)return;const f=e.frame;if(f.type==='mode2_error')return this.abort(`上传失败：${f.reason}`);if(this.uploadState==='begin'&&f.type==='mode2_upload_begin_ok'){this.uploadState='note';return this.sendNote()}if(this.uploadState==='note'&&f.type==='mode2_upload_note_ok'){if(f.index!==this.uploadIndex+1)return this.abort('音符确认序号异常');this.uploadIndex++;if(this.uploadIndex<this.uploadNotes.length)return this.sendNote();this.uploadState='commit';if(!spp.send('M2,UPLOAD,COMMIT\n'))this.abort('提交失败');return}if(this.uploadState==='commit'&&f.type==='mode2_upload_ok'){this.uploading=false;this.uploadState='idle';uni.showToast({title:'上传成功',icon:'success'});setTimeout(()=>uni.navigateBack(),500)}},sendNote(){const n=this.uploadNotes[this.uploadIndex];if(!spp.send(`M2,UPLOAD,NOTE,${n.timeMs},${n.note}\n`))this.abort('上传失败，请重新连接')},abort(message,sendCancel=true){const active=this.uploading;this.uploading=false;this.uploadState='idle';if(active&&sendCancel&&spp.socket)spp.send('M2,UPLOAD,CANCEL\n');uni.showToast({title:message,icon:'none'})},cancelUpload(){this.abort('已取消上传')}}}
</script>
<style>.page{min-height:100vh;padding:36rpx;background:#161424;color:#f8f6ff;box-sizing:border-box}.title{display:block;margin-bottom:28rpx;font-size:46rpx;font-weight:700}.field,.note{margin-bottom:18rpx;padding:22rpx;background:#211d35;border-radius:18rpx}.field text{display:block;margin-bottom:10rpx;color:#bfa7ff}.field input,.note input,.note picker{padding:12rpx;background:#151321;color:#fff;border-radius:10rpx}.row,.actions,.note{display:flex;gap:14rpx;align-items:center}.row view{flex:1}.row button,.actions button,.note button{margin:0;background:#2b2644;color:#d6c8ff;border:0;font-size:22rpx}.note input{width:180rpx}.note picker{flex:1}.note button{color:#ffb9c1}.summary{display:block;margin:24rpx 0;color:#aaa5bd}.upload,.cancel{border:0;border-radius:18rpx}.upload{background:#8d5ee8;color:#fff}.cancel{margin-top:16rpx;color:#ffb9c1;background:#41263b}</style>
